package br.vbrasfoot;

import java.nio.file.*;
import java.net.*;
import java.util.*;
import javax.tools.ToolProvider;

/** Structural fixtures generated by this test, never an authenticity proof for a supplied serializer. */
public final class LedgerSerializerProfileSelfTest {
    private static int checks;
    private static void check(boolean value, String label) { if (!value) throw new AssertionError(label); checks++; }
    public static void main(String[] args) throws Exception {
        Path root = Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("java.io.tmpdir"), "opencode")), "ledger-profile-");
        Path best = Files.createDirectories(root.resolve("best")), serializers = Files.createDirectories(root.resolve("com/esotericsoftware/kryo/serializers"));
        var longs = Set.of("dK", "dN", "dR", "dS"); var source = new StringBuilder("package best; public class C {");
        for (String name : new TreeSet<>(FinanceDelta.FIELDS)) source.append("public ").append(longs.contains(name) ? "long " : "int ").append(name).append(';');
        Path ledgerSource = best.resolve("C.java"); Files.writeString(ledgerSource, source.append('}').toString());
        Path fieldSource = serializers.resolve("FieldSerializer.java");
        Files.writeString(fieldSource, """
            package com.esotericsoftware.kryo.serializers;
            public class FieldSerializer {
                public boolean regions, transients; public Class<?> type = best.C.class; public CachedField[] fields;
                public FieldSerializer() throws Exception {
                    var declared = best.C.class.getFields(); fields = new CachedField[declared.length];
                    for (int i = 0; i < declared.length; i++) fields[i] = declared[i].getType() == long.class
                        ? new UnsafeCacheFields.UnsafeLongField(declared[i]) : new UnsafeCacheFields.UnsafeIntField(declared[i]);
                }
                public boolean getUseMemRegions() { return regions; }
                public boolean getSerializeTransient() { return transients; }
                public Class<?> getType() { return type; }
                public CachedField[] getFields() { return fields; }
                public static class CachedField { public java.lang.reflect.Field field; public CachedField(java.lang.reflect.Field f) { field = f; } public java.lang.reflect.Field getField() { return field; } }
            }
            """);
        Path cachedSource = serializers.resolve("UnsafeCacheFields.java"); Files.writeString(cachedSource, """
            package com.esotericsoftware.kryo.serializers;
            public class UnsafeCacheFields {
                public static class UnsafeIntField extends FieldSerializer.CachedField { public UnsafeIntField(java.lang.reflect.Field f) { super(f); } }
                public static class UnsafeLongField extends FieldSerializer.CachedField { public UnsafeLongField(java.lang.reflect.Field f) { super(f); } }
            }
            """);
        check(ToolProvider.getSystemJavaCompiler().run(null, null, null, "-d", root.toString(), ledgerSource.toString(), fieldSource.toString(), cachedSource.toString()) == 0,
                "generated metadata fixtures compile without original game code");
        try (var loader = new URLClassLoader(new URL[]{root.toUri().toURL()}, null)) {
            Class<?> type = Class.forName("com.esotericsoftware.kryo.serializers.FieldSerializer", true, loader);
            Object ledger = Class.forName("best.C", true, loader).getConstructor().newInstance(), serializer = type.getConstructor().newInstance();
            java.util.concurrent.Callable<LedgerSerializerProfile.Status> inspect = () -> LedgerSerializerProfile.inspect(serializer, ledger, loader);
            check(LedgerSerializerProfile.inspect(serializer, ledger, loader) == LedgerSerializerProfile.Status.WRONG_THREAD, "off-EDT refused before metadata reads");
            check(CareerBridge.onEdt(inspect) == LedgerSerializerProfile.Status.SUPPORTED_SAMPLED_LAYOUT, "exact owned metadata structure qualified, not artifact authenticity");
            type.getField("regions").setBoolean(serializer, true);
            check(CareerBridge.onEdt(inspect) == LedgerSerializerProfile.Status.MEMORY_REGIONS, "memory regions rejected"); type.getField("regions").setBoolean(serializer, false);
            type.getField("transients").setBoolean(serializer, true);
            check(CareerBridge.onEdt(inspect) == LedgerSerializerProfile.Status.TRANSIENT_SERIALIZATION, "transient mode rejected"); type.getField("transients").setBoolean(serializer, false);
            type.getField("type").set(serializer, String.class);
            check(CareerBridge.onEdt(inspect) == LedgerSerializerProfile.Status.WRONG_TYPE, "wrong type rejected"); type.getField("type").set(serializer, ledger.getClass());
            Object fields = type.getField("fields").get(serializer), first = java.lang.reflect.Array.get(fields, 0);
            java.lang.reflect.Array.set(fields, 0, null);
            check(CareerBridge.onEdt(inspect) == LedgerSerializerProfile.Status.UNSUPPORTED_FIELD_ROUTE, "null cached route rejected");
            java.lang.reflect.Array.set(fields, 0, java.lang.reflect.Array.get(fields, 1));
            check(CareerBridge.onEdt(inspect) == LedgerSerializerProfile.Status.FIELD_SET_MISMATCH, "duplicate fields rejected");
            Class<?> base = Class.forName("com.esotericsoftware.kryo.serializers.FieldSerializer$CachedField", true, loader);
            Object custom = base.getConstructor(java.lang.reflect.Field.class).newInstance(base.getMethod("getField").invoke(first));
            java.lang.reflect.Array.set(fields, 0, custom);
            check(CareerBridge.onEdt(inspect) == LedgerSerializerProfile.Status.UNSUPPORTED_FIELD_ROUTE, "unknown cached subclass cannot qualify");
            java.lang.reflect.Array.set(fields, 0, first);
            check(CareerBridge.onEdt(inspect) == LedgerSerializerProfile.Status.SUPPORTED_SAMPLED_LAYOUT, "read-only inspection makes no sticky profile mutation");
            type.getField("fields").set(serializer, java.lang.reflect.Array.newInstance(base, 13));
            check(CareerBridge.onEdt(inspect) == LedgerSerializerProfile.Status.FIELD_SET_MISMATCH, "incomplete inventory rejected");
            type.getField("fields").set(serializer, null);
            check(CareerBridge.onEdt(inspect) == LedgerSerializerProfile.Status.FIELD_SET_MISMATCH, "null field set rejected");
            check(CareerBridge.onEdt(() -> LedgerSerializerProfile.inspect(serializer, ledger, new ClassLoader() { })) == LedgerSerializerProfile.Status.WRONG_TYPE, "foreign runtime rejected");
            check(CareerBridge.onEdt(() -> LedgerSerializerProfile.inspect(null, ledger, loader)) == LedgerSerializerProfile.Status.WRONG_TYPE, "missing serializer rejected");
        }
        System.out.println("PASS: " + checks + " sampled ledger profile checks; own structural fixtures " + root + "; not execution confinement or inclusion.");
    }
}
